//! Complete dispatch/error goldens from20 frozen access tests and Unicode probes.
use localbrain_core::backend::{atlassian::access, db};
use rusqlite::{params_from_iter, types::Value as SqlValue, Connection};
use serde_json::{json, Value};
fn database() -> Connection {
    let db = Connection::open_in_memory().unwrap();
    db.execute_batch("PRAGMA foreign_keys=ON").unwrap();
    db.execute_batch(db::SCHEMA).unwrap();
    db
}
fn restore(db: &Connection, table: &str, rows: &Value) {
    for row in rows.as_array().unwrap() {
        let row = row.as_object().unwrap();
        let columns = row.keys().map(String::as_str).collect::<Vec<_>>();
        let sql = format!(
            "INSERT INTO {table}({}) VALUES ({})",
            columns.join(","),
            vec!["?"; columns.len()].join(",")
        );
        let values = columns
            .iter()
            .map(|key| match &row[*key] {
                Value::Null => SqlValue::Null,
                Value::String(value) => SqlValue::Text(value.clone()),
                Value::Number(value) => SqlValue::Integer(value.as_i64().unwrap()),
                other => panic!("unexpected fixture scalar {other}"),
            })
            .collect::<Vec<_>>();
        db.execute(&sql, params_from_iter(values)).unwrap();
    }
}
#[test]
fn dispatch_and_refusal_match_frozen_policy_and_unicode_boundaries() {
    let cases: Vec<Value> = serde_json::from_str(CASES).unwrap();
    assert_eq!(cases.len(), 53);
    for case in cases {
        let db = database();
        restore(&db, "external_source_instances", &case["sources"]);
        restore(&db, "external_source_capabilities", &case["capabilities"]);
        let result = access::authorize_external_read(
            &db,
            case["source_instance_id"].as_i64().unwrap(),
            case["logical_operation"].as_str().unwrap(),
            &case["arguments"],
        );
        if let Some(error) = case.get("error") {
            let actual = result.unwrap_err();
            assert_eq!(
                json!({"code":actual.code,"message":actual.message}),
                *error,
                "{}",
                case["case"]
            );
        } else {
            assert_eq!(
                serde_json::to_value(result.unwrap_or_else(|error| panic!(
                    "{} {}: {error}",
                    case["case"], case["arguments"]
                )))
                .unwrap(),
                case["expected"],
                "{}",
                case["case"]
            );
        }
    }
    assert_eq!(
        access::policy_manifest(),
        serde_json::from_str::<Value>(POLICY).unwrap()
    );
}
#[test]
fn capability_identity_binding_and_tampering_keep_fail_closed_states() {
    let db = database();
    let initial=access::register_source_instance(&db,&json!({"instance_key":"synthetic-jira","provider_kind":"mcp_gateway","service":"jira","display_name":"Synthetic"})).unwrap();
    let id = initial["id"].as_i64().unwrap();
    assert_eq!(
        access::capability_state(&db, id).unwrap()["state"],
        "unknown"
    );
    assert_eq!(
        access::authorize_external_read(&db, id, "capability.list_tools", &json!({}))
            .unwrap()
            .tool_name,
        "mcp_gateway.gateway_list"
    );
    let renamed=access::register_source_instance(&db,&json!({"instance_key":"synthetic-jira","provider_kind":"mcp_gateway","service":"jira","display_name":"Renamed"})).unwrap();
    assert_eq!(initial["id"], renamed["id"]);
    let observation = json!({"availability":"available","operations":{"jira.search_metadata":true},"schema_fingerprint":"a".repeat(64),"checked_at":"2026-07-23T00:00:00Z"});
    assert_eq!(
        access::record_capability_observation(&db, id, &observation).unwrap()["state"],
        "current"
    );
    db.execute(
        "UPDATE external_source_capabilities SET capability_json='{}' WHERE source_instance_id=?",
        [id],
    )
    .unwrap();
    assert_eq!(access::capability_state(&db, id).unwrap()["state"], "error");
    access::record_capability_observation(&db, id, &observation).unwrap();
    access::bind_source_instance_config_ref(&db, id, &json!("synthetic-alias")).unwrap();
    assert_eq!(access::capability_state(&db, id).unwrap()["state"], "stale");
    assert_eq!(
        access::bind_source_instance_config_ref(&db, id, &json!("other-alias"))
            .unwrap_err()
            .code,
        "source-instance-identity-conflict"
    );
    access::record_capability_observation(&db, id, &observation).unwrap();
    access::set_source_instance_enabled(&db, id, false).unwrap();
    assert_eq!(
        access::capability_state(&db, id).unwrap()["state"],
        "disabled"
    );
    assert_eq!(
        access::authorize_external_read(&db, id, "capability.list_tools", &json!({}))
            .unwrap_err()
            .code,
        "capability-not-current"
    );
}
